<script setup lang="ts">
import type { components } from '~/api/schema'; import { displayError } from '~/utils/errors'; import { formatRupiah, variantLabel } from '~/utils/format';
type CartItem = components['schemas']['CartItem'];
definePageMeta({ middleware: 'auth' }); const cartApi = useCart(); const selected = reactive<Record<string, boolean>>({}); const quantities = reactive<Record<string, number>>({}); const mutationError = ref('');
const { itemIds: checkoutItemIds } = useCheckoutState();
onMounted(() => { void cartApi.load().catch(() => undefined); });
watch(() => cartApi.cart.value?.items, items => { for (const item of items ?? []) { if (!(item.id in selected)) selected[item.id] = true; quantities[item.id] = item.quantity; } }, { immediate: true, deep: true });
const groups = computed(() => { const result = new Map<string, { name: string; items: CartItem[] }>(); for (const item of cartApi.cart.value?.items ?? []) { const group: { name: string; items: CartItem[] } = result.get(item.store_id) ?? { name: item.store_name, items: [] }; group.items.push(item); result.set(item.store_id, group); } return [...result.entries()].map(([id,value]) => ({ id, ...value })); });
const chosen = computed(() => cartApi.cart.value?.items.filter(item => selected[item.id]) ?? []);
const total = computed(() => chosen.value.reduce((sum,item) => sum + item.unit_price_gross * item.quantity, 0));
const invalid = computed(() => chosen.value.some(item => item.product_status !== 'ACTIVE' || item.sku_status !== 'ACTIVE' || item.available_quantity < item.quantity));
function groupSelected(items: CartItem[]) { return items.every(item => selected[item.id]); }
function toggleGroup(items: CartItem[], value: boolean) { for (const item of items) selected[item.id] = value; }
async function update(item: CartItem) { const value = Math.floor(Number(quantities[item.id])); if (!Number.isSafeInteger(value) || value < 1 || value > item.available_quantity) { mutationError.value = `Jumlah ${item.product_name} harus antara 1 dan ${item.available_quantity}.`; quantities[item.id] = item.quantity; return; } mutationError.value = ''; try { await cartApi.update(item.id, value); } catch (cause) { mutationError.value = displayError(cause).message; } }
async function remove(item: CartItem) { mutationError.value = ''; try { await cartApi.remove(item.id); delete selected[item.id]; } catch (cause) { mutationError.value = displayError(cause).message; } }
async function checkout() { if (!chosen.value.length || invalid.value) return; checkoutItemIds.value = chosen.value.map(item => item.id); await navigateTo('/akun/checkout'); }
useSeoMeta({ title: 'Keranjang — Niaga' });
</script>
<template><main id="main-content" class="page-shell"><div class="section-heading"><div><p class="eyebrow">Belanja</p><h1>Keranjang</h1><p class="muted">Item dikelompokkan per toko agar ongkir dan pemenuhan tetap jelas.</p></div></div><ApiState :pending="cartApi.pending.value && !cartApi.cart.value" :error="cartApi.error.value ? displayError(cartApi.error.value) : null" :empty="Boolean(cartApi.cart.value && !cartApi.cart.value.items.length)" empty-title="Keranjang masih kosong" empty-message="Cari produk yang Anda perlukan dan tambahkan ke keranjang." @retry="cartApi.load"><template #action><NuxtLink class="button" to="/cari">Mulai belanja</NuxtLink></template><div class="cart-layout"><section aria-label="Item keranjang"><p v-if="mutationError" class="error surface" role="alert">{{ mutationError }}</p><article v-for="group in groups" :key="group.id" class="cart-store"><header class="cart-store__head"><label class="checkbox"><input type="checkbox" :checked="groupSelected(group.items)" @change="toggleGroup(group.items, ($event.target as HTMLInputElement).checked)"><strong>{{ group.name }}</strong></label><NuxtLink :to="`/toko/${group.id}`">Lihat toko</NuxtLink></header><div v-for="item in group.items" :key="item.id" class="cart-item"><NuxtLink class="cart-item__image" :to="`/produk/${item.product_id}`"><img v-if="item.image_url" :src="item.image_url" :alt="item.product_name"><span v-else>NIAGA</span></NuxtLink><div><label class="checkbox"><input v-model="selected[item.id]" type="checkbox"><span><h3>{{ item.product_name }}</h3><span class="muted">{{ variantLabel(item.variant_attributes) || item.sku_code }}</span></span></label><span v-if="item.quote_line_id" class="badge badge--warning">Harga penawaran · jumlah terkunci</span><p v-if="item.product_status !== 'ACTIVE' || item.sku_status !== 'ACTIVE'" class="error">Item sudah tidak aktif.</p><p v-else-if="item.available_quantity < item.quantity" class="error">Stok tersisa {{ item.available_quantity }}. Sesuaikan jumlah.</p><button class="text-button" type="button" :disabled="cartApi.pending.value" @click="remove(item)">Hapus</button></div><label class="quantity-control">Jumlah<input v-model.number="quantities[item.id]" type="number" min="1" :max="item.available_quantity" :disabled="Boolean(item.quote_line_id) || cartApi.pending.value" @change="update(item)"><small class="muted">Stok {{ item.available_quantity }}</small></label><strong class="cart-price">{{ formatRupiah(item.unit_price_gross * item.quantity) }}</strong></div></article></section><aside class="surface order-summary"><h2>Ringkasan</h2><div class="summary-line"><span>Item dipilih</span><strong>{{ chosen.length }}</strong></div><div class="summary-line summary-total"><span>Total produk</span><strong>{{ formatRupiah(total) }}</strong></div><p class="muted">Ongkir, pajak, dan biaya lain dihitung pada checkout.</p><p v-if="invalid" class="error">Perbaiki item bermasalah sebelum checkout.</p><button :disabled="!chosen.length || invalid" type="button" @click="checkout">Lanjut ke checkout</button></aside></div></ApiState></main></template>
